SELECT ?region ?regionEn ?code (COUNT(DISTINCT ?country) AS ?n) (GROUP_CONCAT(DISTINCT ?countryEn; separator="; ") AS ?countries) WHERE {
  VALUES ?code { "154" "151" "039" "155" }
  ?region wdt:P2082 ?code .
  OPTIONAL { ?region rdfs:label ?regionEn FILTER(LANG(?regionEn) = "en") }
  ?country wdt:P361 ?region ; wdt:P31 wd:Q3624078 .
  OPTIONAL { ?country rdfs:label ?countryEn FILTER(LANG(?countryEn) = "en") }
}
GROUP BY ?region ?regionEn ?code
